```
func isPrime(_ number: Int) -> Bool {
    if number < 2 {
        return false
    }
    for i in 2..<number {
        if number % i == 0 {
            return false
        }
    }
    return true
}
func findTwinPrimes(_ start: Int, _ end: Int) -> [(Int, Int)] {
    var twinPrimes: [(Int, Int)] = []
    for i in start...end {
        if isPrime(i) && isPrime(i + 2) {
            twinPrimes.append((i, i + 2))
        }
    }
    return twinPrimes
}
let twinPrimes = findTwinPrimes(1, 100)
print(twinPrimes)
```
The `isPrime` function checks if a number is prime by iterating from 2 up to the number - 1 and checking if the number is divisible by any of those values. If it is, then it's not prime. If it's not, then it's prime.
The `findTwinPrimes` function takes a start and end value and iterates through each number in that range. If a number is prime and the next number after it (i + 2) is also prime, then it's a twin prime and it's added to the `twinPrimes` array.
When you call `findTwinPrimes(1, 100)`, it will return an array of tuples representing the twin prime numbers between 1 and 100.

