Here's a C++ program that solves the problem using a priority queue:
```
#include <iostream>
#include <queue>
#include <vector>
using namespace std;
struct Item {
    int size, importance;
};
bool operator<(const Item& a, const Item& b) {
    return a.importance < b.importance;
}
int main() {
    int n; // number of items
    cin >> n;
    vector<Item> items(n);
    for (int i = 0; i < n; i++) {
        cin >> items[i].size >> items[i].importance;
    }
    vector<int> containerSizes = {8, 7, 6, 4}; // container sizes
    priority_queue<Item> pq;
    for (int i = 0; i < n; i++) {
        pq.push(items[i]);
    }
    int maxImportance = 0;
    for (int i = 0; i < containerSizes.size(); i++) {
        int remainingSize = containerSizes[i];
        priority_queue<Item> tempPq = pq;
        int importance = 0;
        while (!tempPq.empty() && remainingSize >= tempPq.top().size) {
            Item item = tempPq.top();
            tempPq.pop();
            remainingSize -= item.size;
            importance += item.importance;
        }
        maxImportance += importance;
    }
    cout << "Maximum total importance level: " << maxImportance << endl;
    return 0;
}
```
The program first reads in the number of items and their sizes and importance levels. It then creates a vector of container sizes and a priority queue of items sorted by importance level.
For each container size, the program creates a copy of the priority queue and iterates through it, adding items to the container as long as they fit. The importance level of the items added to the container is summed up and added to the maximum total importance level.
Finally, the program outputs the maximum total importance level.
Note that this program assumes that there are exactly four containers with the given sizes. If the number of containers or their sizes are variable, the program would need to be modified accordingly.

