```
This formula uses the golden ratio `(1 + sqrt(5)) / 2` and its inverse `(1 - sqrt(5)) / 2` to compute the `n`-th Fibonacci number. The `sqrt(5)` factor ensures that the result is an integer.
Here's an implementation of this formula in Swift:
```swift
func fibonacci(_ n: Int) -> Int {
    let sqrt5 = sqrt(5.0)
    let phi = (1.0 + sqrt5) / 2.0
    let psi = (1.0 - sqrt5) / 2.0
    let fn = (pow(phi, Double(n)) - pow(psi, Double(n))) / sqrt5
    return Int(round(fn))
}
