```
import math
# Function to check if a number is prime
def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True
# Function to check if a number is a perfect square
def is_perfect_square(n):
    root = int(math.sqrt(n))
    return root * root == n
# Equation solver function
def solve_equation(a, b, c):
    solutions = []
    discriminant = b * b - 4 * a * c
    if discriminant < 0:
        return solutions
    elif discriminant == 0:
        x = -b / (2 * a)
        if is_prime(x) and is_perfect_square(a):
            solutions.append((x, x, True))
        else:
            solutions.append((x, x, False))
    else:
        x1 = (-b + math.sqrt(discriminant)) / (2 * a)
        x2 = (-b - math.sqrt(discriminant)) / (2 * a)
        if is_prime(x1) and is_prime(x2) and is_perfect_square(a):
            solutions.append((x1, x2, True))
        else:
            solutions.append((x1, x2, False))
    return solutions
# Example usage
equations = [(4, 10, 6), (9, 15, 6), (2, 8, 6), (25, 10, 1)]
for a, b, c in equations:
    solutions = solve_equation(a, b, c)
    for x1, x2, satisfies_conditions in solutions:
        print(f"Equation {a}x^2 + {b}x + {c} has solutions x1 = {x1} and x2 = {x2}. Satisfies conditions: {satisfies_conditions}")
