```
import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.StringTokenizer;
public class ReadCSVFile {
    public static void main(String[] args) {
        String csvFile = "path/to/your/csv/file.csv";
        BufferedReader br = null;
        String line = "";
        String cvsSplitBy = ",";
        try {
            br = new BufferedReader(new FileReader(csvFile));
            while ((line = br.readLine()) != null) {
                // use comma as separator
                StringTokenizer st = new StringTokenizer(line, cvsSplitBy);
                String title = st.nextToken();
                String author = st.nextToken();
                String publisher = st.nextToken();
                int publicationYear = Integer.parseInt(st.nextToken());
                if (publicationYear > 1950) {
                    System.out.println(title + ", " + author + ", " + publisher + ", " + publicationYear);
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            if (br != null) {
                try {
                    br.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
    }
}
```
In this example, we first define the path to the CSV file we want to read. Then, we create a BufferedReader object to read the file line by line. We use a StringTokenizer to split each line into its respective columns, using a comma as the separator. We then extract the publication year column and convert it to an integer. Finally, we check if the publication year is greater than 1950, and if it is, we output the entire row to the console.
